/*!50003 CREATE*/ /*!50017 DEFINER=`PTGR`@`localhost`*/ /*!50003 TRIGGER `prevent_shipping_address_insert` BEFORE INSERT ON `addresses` FOR EACH ROW BEGIN
  DECLARE shipping_same INT;

  
  IF NEW.address_type = 'shipping' THEN
    
    SELECT isShippingTheSame INTO shipping_same
    FROM customers
    WHERE customer_id = NEW.customer_id;

    
    IF shipping_same = 1 THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Shipping address not allowed: isShippingTheSame is set to true for this customer.';
    END IF;
  END IF;
END */;;
