CREATE TABLE `customer_section_quiz_status` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `customer_id` bigint NOT NULL,
  `section_id` bigint unsigned NOT NULL,
  `status` enum('not_started','passed','failed') NOT NULL DEFAULT 'not_started',
  `score` int NOT NULL DEFAULT '0',
  `attempts` int NOT NULL DEFAULT '0',
  `last_attempt_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_customer_section` (`customer_id`,`section_id`),
  UNIQUE KEY `uniq_customer_subsection` (`customer_id`,`section_id`),
  KEY `fk_c_sqs_subsection` (`section_id`),
  CONSTRAINT `customer_section_quiz_status_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`customer_id`),
  CONSTRAINT `fk_c_sqs_subsection` FOREIGN KEY (`section_id`) REFERENCES `subsections` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1142 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
