--
-- Table structure for table `customers`
--

DROP TABLE IF EXISTS `customers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `customers` (
  `customer_id` bigint NOT NULL AUTO_INCREMENT,
  `telegram_user_id` bigint DEFAULT NULL,
  `telegram_username` varchar(255) DEFAULT NULL,
  `email` varchar(255) NOT NULL,
  `phone` varchar(255) NOT NULL DEFAULT '99999999999',
  `is_active` tinyint(1) DEFAULT '1',
  `first_name` varchar(100) NOT NULL,
  `last_name` varchar(100) NOT NULL,
  `profile_picture` varchar(255) DEFAULT NULL,
  `date_of_birth` date DEFAULT NULL,
  `gender` enum('male','female','other','prefer_not_to_say') DEFAULT 'prefer_not_to_say',
  `is_email_verified` tinyint(1) DEFAULT '0',
  `is_phone_verified` tinyint(1) DEFAULT '0',
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `phone_verified_at` timestamp NULL DEFAULT NULL,
  `two_factor_enabled` tinyint(1) DEFAULT '0',
  `referral_code` varchar(20) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `is_kyc_verified` tinyint(1) DEFAULT '0' COMMENT '0 = not verified, 1 = verified',
  `signature_url` varchar(255) DEFAULT NULL,
  `customer_type` enum('individual','enterprise') NOT NULL DEFAULT 'individual',
  `isShippingTheSame` tinyint(1) NOT NULL DEFAULT '0',
  `referral_index` int unsigned DEFAULT NULL,
  `referred_by` varchar(255) DEFAULT NULL,
  `source` varchar(255) DEFAULT NULL,
  `telegram_id` bigint DEFAULT '0',
  PRIMARY KEY (`customer_id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `phone` (`phone`),
  UNIQUE KEY `referral_index` (`referral_index`),
  UNIQUE KEY `telegram_user_id` (`telegram_user_id`),
  KEY `idx_customer_name` (`first_name`,`last_name`),
  KEY `idx_customer_status` (`is_active`,`deleted_at`),
  KEY `idx_telegram_user_id` (`telegram_user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=101182 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

