--
-- Table structure for table `subsections`
--

DROP TABLE IF EXISTS `subsections`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `subsections` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `section_id` bigint unsigned NOT NULL,
  `title` varchar(255) NOT NULL,
  `content_html` longtext NOT NULL,
  `sort_order` int DEFAULT '0',
  `quiz_required` tinyint(1) NOT NULL DEFAULT '0',
  `quiz_pass_score` int NOT NULL DEFAULT '70',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_subsections_section` (`section_id`,`sort_order`),
  CONSTRAINT `fk_subsections_section` FOREIGN KEY (`section_id`) REFERENCES `sections` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=262 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
